        if(auto recall=std::get_if<LanActionGroupSelect>(&event)){std::vector<std::uint32_t> members;for(auto id:projectedGroups_[*player][recall->group]){auto found=session_.units().find(id);if(found!=session_.units().end() && session_.unitSelectable(id) && !found->second->hidden() && std::bit_cast<float>(found->second->life.bits())>0 && session_.canControlUnit(*player,*found->second) && session_.unitVisibleTo(id,*player))members.push_back(id);}if(!members.empty()){selected()=std::set<std::uint32_t>(members.begin(),members.end());projectedSubgroups_.erase(*player);prepared.emplace_back(GroupSelect{*player,std::move(members)});}continue;}
