        if(auto alliance=std::get_if<LanActionAlliance>(&event)){auto recipient=session_.networkSlotPlayer(alliance->slot);if(!recipient || (alliance->flags&~0x47fu))return false;prepared.emplace_back(Alliance{*player,*recipient,alliance->flags});continue;}
        if(auto transfer=std::get_if<LanActionTransfer>(&event)){auto recipient=session_.networkSlotPlayer(transfer->slot);if(!recipient || *recipient==*player || transfer->gold>0x7fffffffu || transfer->lumber>0x7fffffffu)return false;prepared.emplace_back(Transfer{*player,*recipient,int(transfer->gold),int(transfer->lumber)});continue;}
        if(auto cancel=std::get_if<LanActionCancelRevival>(&event)){if(!resolve_)return false;auto hero=resolve_(cancel->hero);if(!hero || !session_.units().contains(*hero) || !session_.units().at(*hero)->hero)return false;prepared.emplace_back(CancelRevival{*player,*hero});continue;}
        if(auto cancel=std::get_if<LanActionCancelQueue>(&event)){auto& units=selected();if(units.size()!=1 || cancel->slot>6 || !cancel->type)return false;Command command;command.player=*player;command.kind=PlayerCommandKind::CancelProduction;command.expectedUnit=*units.begin();command.queueIndex=cancel->slot;command.expectedType=cancel->type;prepared.emplace_back(command);continue;}
        auto ability=std::get_if<LanActionAbility>(&event);if(!ability || !resolve_ || ((ability->flags&~1u)!=0 && (ability->flags&~1u)!=8 && (ability->flags&~1u)!=0x40))return false;Command command;command.subgroup=(ability->flags&0x40u)!=0;command.queued=(ability->flags&1u)!=0;command.player=*player;command.order=ability->order;command.xBits=ability->xBits;command.yBits=ability->yBits;auto actor=[&]() -> std::optional<std::uint32_t>{auto& units=selected();if(!command.subgroup)return units.size()==1?std::optional<std::uint32_t>{*units.begin()}:std::nullopt;auto group=projectedSubgroups_.find(*player);if(group==projectedSubgroups_.end() || !units.contains(group->second.first))return {};auto unit=session_.units().find(group->second.first);if(unit==session_.units().end() || unit->second->type!=group->second.second)return {};unsigned same=0;for(auto id:units){auto item=session_.units().find(id);if(item!=session_.units().end() && item->second->type==group->second.second)++same;}return same==1?std::optional<std::uint32_t>{unit->first}:std::nullopt;};auto production=[&](bool point)->std::optional<PlayerCommandKind>{auto unit=actor();if(!unit || !session_.units().contains(*unit))return {};return lanProductionOrder(*session_.units().at(*unit),ability->order,point);};
