        if(ability->order>=852008 && ability->order<=852013){auto unit=actor();if(!unit || !session_.units().contains(*unit))return false;auto holder=session_.units().at(*unit);auto index=ability->order-852008;auto id=holder->inventory[index];auto item=session_.items().find(id);if(!id || item==session_.items().end() || item->second->holder!=*unit || !session_.canManageUnitInventory(*player,*holder))return false;command.expectedUnit=*unit;command.expectedItem=id;command.itemSlot=index;command.itemOrder=true;if(command.subgroup)command.expectedType=holder->type;
            if(ability->opcode==0x10)command.kind=PlayerCommandKind::ItemImmediate;else if(ability->opcode==0x11){if(!finitePoint(ability->xBits,ability->yBits))return false;command.kind=PlayerCommandKind::ItemPoint;}else if(ability->opcode==0x12){if(!finitePoint(ability->xBits,ability->yBits))return false;auto target=resolve_(ability->target);if(!target || !session_.units().contains(*target))return false;command.kind=PlayerCommandKind::ItemUnit;command.target=*target;}else return false;prepared.emplace_back(command);continue;}
        if(ability->opcode==0x10){if(ability->order==851972)command.kind=PlayerCommandKind::Stop;else if(ability->order==851993)command.kind=PlayerCommandKind::Hold;else if(ability->order==851976){command.kind=PlayerCommandKind::CancelBuild;command.constructionCancel=true;}else if(lanSpellOrder(ability->order,LanSpellTarget::None))command.kind=PlayerCommandKind::SpellImmediateOrder;else if(auto kind=production(false))command.kind=*kind;else return false;}
        else if(ability->opcode==0x11){auto kind=groundKind(ability->order);if(!finitePoint(ability->xBits,ability->yBits))return false;if(kind)command.kind=*kind;else if(lanSpellOrder(ability->order,LanSpellTarget::Point))command.kind=PlayerCommandKind::SpellPointOrder;else if(auto productionKind=production(true))command.kind=*productionKind;else return false;}
        else if(ability->opcode==0x12){if(ability->target.first==0xffffffffu && ability->target.second==0xffffffffu){auto kind=groundKind(ability->order);if(!kind || !finitePoint(ability->xBits,ability->yBits))return false;command.kind=*kind;}else{bool awakening=ability->order==852466,revival=ability->order==852039 || awakening,spell=lanSpellOrder(ability->order,LanSpellTarget::Unit);if(!finitePoint(ability->xBits,ability->yBits))return false;if(!revival && !spell && !targetOrder(ability->order))return false;auto handle=resolve_(ability->target);if(!handle || (!session_.units().contains(*handle) && !session_.items().contains(*handle) && !session_.destructables().contains(*handle)))return false;if((spell || revival) && !session_.units().contains(*handle))return false;if(revival && !session_.units().at(*handle)->hero)return false;command.kind=awakening?PlayerCommandKind::Awaken:revival?PlayerCommandKind::Revive:spell?PlayerCommandKind::SpellUnitOrder:PlayerCommandKind::TargetOrder;command.target=*handle;}}
        else return false;if(command.queued && !playerCommandQueueable(command.kind))return false;bool spell=command.kind==PlayerCommandKind::SpellUnitOrder || command.kind==PlayerCommandKind::SpellPointOrder || command.kind==PlayerCommandKind::SpellImmediateOrder;bool productionOrder=command.kind==PlayerCommandKind::BuildAt || command.kind==PlayerCommandKind::Train || command.kind==PlayerCommandKind::Research || command.kind==PlayerCommandKind::Upgrade;if(command.subgroup && !spell && !productionOrder)return false;if(spell || productionOrder || command.constructionCancel || (command.kind==PlayerCommandKind::Revive || command.kind==PlayerCommandKind::Awaken)){auto unit=actor();if(!unit)return false;command.expectedUnit=*unit;if(command.subgroup)command.expectedType=session_.units().at(*unit)->type;}prepared.emplace_back(command);
