bool LanSimulation::apply(ScriptSession& session,const LanAction&){
    if(cursor_>=decoded_.size())return false;
    for(const auto& event:decoded_[cursor_++]){
        if(std::holds_alternative<LanActionPause>(event))session.pause(true);
        else if(std::holds_alternative<LanActionResume>(event))session.pause(false);
        else if(auto escape=std::get_if<Escape>(&event))session.endCinematic(escape->player);
        else if(auto chat=std::get_if<Chat>(&event)){session.chat(chat->player,chat->text,chat->channel);if(driver_.failed())return false;}
        else if(auto sync=std::get_if<SelectionSync>(&event)){session.receiveSelectionSync(sync->peer,sync->part);if(driver_.failed())return false;}
        else if(auto trackable=std::get_if<Trackable>(&event)){session.trackableEvent(trackable->handle,trackable->hit);if(driver_.failed())return false;}
        else if(auto selection=std::get_if<Selection>(&event)){for(auto id:selection->units){session.setPlayerUnitSelected(selection->player,id,selection->add);if(driver_.failed())return false;}auto group=subgroups_.find(selection->player);if(group!=subgroups_.end() && !session.playerSelection(selection->player).contains(group->second.first))subgroups_.erase(group);}
        else if(auto assigned=std::get_if<GroupAssign>(&event)){groups_[assigned->player][assigned->group]=assigned->units;}
        else if(auto recalled=std::get_if<GroupSelect>(&event)){auto old=session.playerSelection(recalled->player);std::set<std::uint32_t> desired(recalled->units.begin(),recalled->units.end());for(auto id:old)if(!desired.contains(id)){session.setPlayerUnitSelected(recalled->player,id,false);if(driver_.failed())return false;}for(auto id:recalled->units)if(!old.contains(id)){session.setPlayerUnitSelected(recalled->player,id,true);if(driver_.failed())return false;}subgroups_.erase(recalled->player);}
        else if(auto group=std::get_if<Subgroup>(&event)){auto selected=session.playerSelection(group->player);auto unit=session.units().find(group->unit);if(!selected.contains(group->unit) || unit==session.units().end() || unit->second->type!=group->type)return false;subgroups_[group->player]={group->unit,group->type};}
        else if(auto alliance=std::get_if<Alliance>(&event)){PlayerCommand command;command.player=alliance->player;command.kind=PlayerCommandKind::AllianceSnapshot;command.otherPlayer=alliance->recipient;command.allianceOption=alliance->flags&0x7fu;command.enabled=(alliance->flags&0x400u)!=0;dispatchPlayerCommand(session,command);if(driver_.failed())return false;}
        else if(auto transfer=std::get_if<Transfer>(&event)){PlayerCommand command;command.player=transfer->player;command.kind=PlayerCommandKind::TransferResources;command.otherPlayer=transfer->recipient;command.gold=transfer->gold;command.lumber=transfer->lumber;dispatchPlayerCommand(session,command);if(driver_.failed())return false;}
        else if(auto cancel=std::get_if<CancelRevival>(&event)){auto hero=session.units().find(cancel->hero);if(hero==session.units().end() || !hero->second->hero || hero->second->removing)continue;auto building=session.units().find(hero->second->revivalBuilding);if(building==session.units().end() || building->second->owner!=hero->second->owner || !session.canControlUnit(cancel->player,*building->second))continue;auto ticket=hero->second->revivalTicket;auto& jobs=building->second->production;auto found=std::find_if(jobs.begin(),jobs.end(),[&](const auto& job){return job.revival && job.hero==cancel->hero && job.ticket==ticket;});if(found==jobs.end())continue;PlayerCommand command;command.player=cancel->player;command.kind=PlayerCommandKind::CancelProduction;command.units={building->first};command.queueIndex=std::uint32_t(found-jobs.begin());dispatchPlayerCommand(session,command);if(driver_.failed())return false;}
        else if(auto source=std::get_if<Command>(&event)){PlayerCommand command;command.player=source->player;command.kind=source->kind;command.queued=source->queued;command.order=source->order;command.target=source->target;command.xBits=source->xBits;command.yBits=source->yBits;auto units=session.playerSelection(source->player);bool production=source->kind==PlayerCommandKind::BuildAt || source->kind==PlayerCommandKind::Train || source->kind==PlayerCommandKind::Research || source->kind==PlayerCommandKind::Upgrade;if(production)command.objectType=source->order;if(source->kind==PlayerCommandKind::Revive || source->kind==PlayerCommandKind::Awaken)command.objectType=source->target;bool spell=source->kind==PlayerCommandKind::SpellUnitOrder || source->kind==PlayerCommandKind::SpellPointOrder || source->kind==PlayerCommandKind::SpellImmediateOrder;bool queueCancel=source->kind==PlayerCommandKind::CancelProduction;if(spell || production || queueCancel || source->itemOrder || source->constructionCancel || (source->kind==PlayerCommandKind::Revive || source->kind==PlayerCommandKind::Awaken)){if(source->subgroup){auto activeGroup=subgroups_.find(source->player);auto unit=session.units().find(source->expectedUnit);if(activeGroup==subgroups_.end() || activeGroup->second.first!=source->expectedUnit || activeGroup->second.second!=source->expectedType || unit==session.units().end() || unit->second->type!=source->expectedType || !units.contains(source->expectedUnit))return false;unsigned same=0;for(auto id:units){auto other=session.units().find(id);if(other!=session.units().end() && other->second->type==source->expectedType)++same;}if(same!=1)return false;units={source->expectedUnit};}else if(units.size()!=1 || *units.begin()!=source->expectedUnit)return false;}if(source->itemOrder){auto holder=session.units().find(source->expectedUnit);auto item=session.items().find(source->expectedItem);if(holder==session.units().end() || item==session.items().end() || (source->itemById?std::find(holder->second->inventory.begin(),holder->second->inventory.end(),source->expectedItem)==holder->second->inventory.end():(source->itemSlot>=holder->second->inventory.size() || holder->second->inventory[source->itemSlot]!=source->expectedItem)) || item->second->holder!=source->expectedUnit || !session.canManageUnitInventory(source->player,*holder->second))continue;command.item=source->expectedItem;if(source->kind==PlayerCommandKind::SwapItem){if(source->queueIndex>=session.inventorySize(*holder->second))continue;command.queueIndex=source->queueIndex;}}if(source->constructionCancel){auto found=session.units().find(source->expectedUnit);if(found==session.units().end())continue;auto& unit=*found->second;if(unit.construction && unit.buildingUpgrade)return false;if(unit.construction)command.kind=PlayerCommandKind::CancelBuild;else if(unit.buildingUpgrade)command.kind=PlayerCommandKind::CancelUpgrade;else continue;}if(queueCancel){auto found=session.units().find(source->expectedUnit);if(found==session.units().end() || source->queueIndex>=found->second->production.size())continue;auto& job=found->second->production[source->queueIndex];if(job.type!=source->expectedType || job.research || job.revival)continue;command.queueIndex=source->queueIndex;}if(source->kind==PlayerCommandKind::GroundMove || source->kind==PlayerCommandKind::GroundAttack || source->kind==PlayerCommandKind::GroundPatrol){command.units.assign(units.begin(),units.end());dispatchPlayerCommand(session,command,[this]{return !driver_.failed();});if(driver_.failed())return false;}else for(auto id:units){command.units={id};dispatchPlayerCommand(session,command);if(driver_.failed())return false;}}
        else return false;if(driver_.failed())return false;
    }
    return true;
}
LanStepResult LanSimulation::consume(std::uint64_t sequence,const LanTimeSlot& slot){
    if(consuming_)return driver_.consume(sequence,slot);consuming_=true;struct Reset{bool& value;~Reset(){value=false;}}reset{consuming_};decoded_.clear();projectedSync_.clear();projectedSelections_.clear();projectedSubgroups_=subgroups_;projectedGroups_=groups_;cursor_=0;auto result=driver_.consume(sequence,slot);decoded_.clear();projectedSync_.clear();projectedSelections_.clear();projectedSubgroups_.clear();projectedGroups_.clear();cursor_=0;return result;
}
